style.css:
@-moz-document domain("discord.com") {
/* 1. VARIABLES GENERALES */

:root,
.theme-dark,
.theme-darker {
    --background-primary: rgba(42, 30, 53, 0.20) !important;
    --background-secondary: rgba(42, 30, 53, 0.24) !important;
    --background-secondary-alt: rgba(42, 30, 53, 0.22) !important;
    --background-tertiary: rgba(42, 30, 53, 0.30) !important;
    --background-floating: rgba(42, 30, 53, 0.96) !important;
    --background-nested-floating: rgba(42, 30, 53, 0.94) !important;

    --bg-base-primary: rgba(42, 30, 53, 0.20) !important;
    --bg-base-secondary: rgba(42, 30, 53, 0.24) !important;
    --bg-base-tertiary: rgba(42, 30, 53, 0.30) !important;
    --bg-surface-raised: rgba(65, 45, 75, 0.35) !important;
    --bg-surface-overlay: rgba(42, 30, 53, 0.96) !important;

    --background-base-lowest: rgba(42, 30, 53, 0.18) !important;
    --background-base-lower: rgba(42, 30, 53, 0.20) !important;
    --background-base-low: rgba(42, 30, 53, 0.22) !important;
    --background-base: rgba(42, 30, 53, 0.24) !important;

    --background-surface-highest: rgba(65, 45, 75, 0.40) !important;
    --background-surface-higher: rgba(65, 45, 75, 0.35) !important;
    --background-surface-high: rgba(65, 45, 75, 0.30) !important;

    --background-mobile-primary: rgba(42, 30, 53, 0.20) !important;
    --background-mobile-secondary: rgba(42, 30, 53, 0.24) !important;
    --channeltextarea-background: rgba(42, 30, 53, 0.55) !important;
    --input-background: rgba(42, 30, 53, 0.45) !important;
    --activity-card-background: rgba(42, 30, 53, 0.40) !important;
    --deprecated-card-bg: rgba(42, 30, 53, 0.30) !important;
    --deprecated-store-bg: transparent !important;

    --background-modifier-hover: rgba(239, 199, 234, 0.18) !important;
    --background-modifier-active: rgba(239, 199, 234, 0.24) !important;
    --background-modifier-selected: rgba(239, 199, 234, 0.22) !important;
    --background-modifier-accent: rgba(239, 199, 234, 0.18) !important;

    /* TEXTO BLANCO */
    --text-normal: #fffaff !important;
    --text-muted: #f0dff2 !important;
    --header-primary: #ffffff !important;
    --header-secondary: #f3e2f4 !important;

    --interactive-normal: #f8eafa !important;
    --interactive-hover: #ffffff !important;
    --interactive-active: #ffffff !important;
    --interactive-muted: #dfc9e2 !important;

    --channels-default: #f3e4f5 !important;
    --text-link: #ffc9ed !important;
}


/* 2. FONDO PERSONALIZADO */

html,
body {
    background: transparent !important;
    background-color: transparent !important;
}

body::before {
    content: "";
    position: fixed;
    inset: 0;
    z-index: -1;
    pointer-events: none;

    background-image: url("https://i.imgur.com/i9v4qcd.jpg");
    background-position: center center;
    background-size: cover;
    background-repeat: no-repeat;
}

#app-mount {
    background: transparent !important;
}


/* 3. ELIMINAR DESENFOQUES */

* {
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
}


/* 4. ESTRUCTURA PRINCIPAL */

[class*="app_"],
[class*="bg_"],
[class*="base_"] {
    background-color: transparent !important;
}


/* 5. SERVIDORES Y BARRA LATERAL */

[class*="guilds_"],
[class*="sidebar_"],
[class*="privateChannels_"] {
    background-color: rgba(42, 30, 53, 0.24) !important;
}

[class*="sidebar_"] [class*="scroller_"],
[class*="sidebar_"] [class*="content_"],
[class*="sidebar_"] [class*="container_"] {
    background-color: transparent !important;
}


/* 6. MENSAJES DIRECTOS */

[class*="privateChannels_"],
[class*="privateChannels_"] [class*="scroller_"],
[class*="privateChannels_"] [class*="content_"],
[class*="privateChannels_"] [class*="channel_"] {
    background-color: transparent !important;
}

[class*="privateChannels_"] [class*="interactive_"] {
    background-color: transparent !important;
}

[class*="privateChannels_"] [class*="interactive_"]:hover {
    background-color: rgba(239, 199, 234, 0.19) !important;
}

[class*="privateChannels_"] [class*="selected_"] {
    background-color: rgba(239, 199, 234, 0.25) !important;
}


/* 7. CONTENEDORES DE DM Y AMIGOS */

[class*="peopleColumn_"],
[class*="peopleList_"],
[class*="peopleListItem_"],
[class*="peopleColumn_"] [class*="scroller_"],
[class*="peopleColumn_"] [class*="container_"],
[class*="peopleColumn_"] [class*="content_"],
[class*="peopleColumn_"] [class*="list_"],
[class*="peopleColumn_"] [class*="tabBody_"],
[class*="peopleColumn_"] [class*="section_"],
[class*="nowPlayingColumn_"],
[class*="homeWrapper_"],
[class*="pageWrapper_"],
[class*="tabBody_"] {
    background-color: transparent !important;
}

/* Tarjetas de amigos */

[class*="peopleListItem_"] {
    border-color: rgba(239, 199, 234, 0.20) !important;
}

[class*="peopleListItem_"]:hover {
    background-color: rgba(239, 199, 234, 0.16) !important;
}


/* 8. FONDOS MODERNOS DE INICIO */

[class*="page_"],
[class*="pageBody_"],
[class*="contentRegion_"],
[class*="contentRegionScroller_"],
[class*="homePage_"],
[class*="friendsPage_"],
[class*="friendsContainer_"],
[class*="peopleContent_"],
[class*="tabContent_"] {
    background-color: transparent !important;
}


/* 9. ACTIVIDAD Y COLUMNA LATERAL */

[class*="nowPlayingColumn_"] [class*="scroller_"],
[class*="nowPlayingColumn_"] [class*="container_"],
[class*="nowPlayingColumn_"] [class*="section_"],
[class*="nowPlayingColumn_"] [class*="item_"] {
    background-color: transparent !important;
}


/* 10. NITRO Y TIENDA */

[class*="shop_"],
[class*="applicationStore_"],
[class*="store_"],
[class*="activity_"] {
    background-color: transparent !important;
}


/* 11. CHAT */

[class*="chat_"],
[class*="chatContent_"],
[class*="messagesWrapper_"],
[class*="scrollerInner_"] {
    background-color: transparent !important;
}

/* FONDO DE MENSAJES — UN POQUITO MÁS TRANSPARENTE */

[class*="message_"] {
    background-color: rgba(25, 15, 35, 0.40) !important;
    border-radius: 8px !important;
}

[class*="message_"]:hover {
    background-color: rgba(25, 15, 35, 0.54) !important;
}


/* 12. CANALES */

[class*="containerDefault_"],
[class*="channel_"] {
    background-color: transparent !important;
}

[class*="modeSelected_"] [class*="link_"] {
    background-color: rgba(239, 199, 234, 0.24) !important;
    border-radius: 8px !important;
}


/* 13. MIEMBROS */

[class*="membersWrap_"],
[class*="members_"] {
    background-color: rgba(42, 30, 53, 0.22) !important;
}

[class*="member_"] {
    background-color: transparent !important;
}


/* 14. TEXTO — BLANCO LEGIBLE */

body,
[class*="messageContent_"],
[class*="username_"],
[class*="headerText_"],
[class*="name_"],
[class*="title_"],
[class*="sectionTitle_"],
[class*="channelName_"],
[class*="label_"],
[class*="tab_"],
[class*="button_"] {
    color: #fffaff !important;
}

/* Texto secundario */

[class*="subtext_"],
[class*="description_"],
[class*="topic_"],
[class*="activityText_"],
[class*="textMuted_"],
[class*="timestamp_"] {
    color: #f0dff2 !important;
}

/* Sombra oscura para separar letras del fondo */

[class*="messageContent_"],
[class*="username_"],
[class*="headerText_"],
[class*="name_"],
[class*="title_"],
[class*="sectionTitle_"],
[class*="channelName_"] {
    text-shadow: 0 1px 3px rgba(15, 8, 22, 0.85) !important;
}


/* 15. CAJA DE MENSAJES */

[class*="channelTextArea_"],
[class*="scrollableContainer_"] {
    background-color: rgba(42, 30, 53, 0.58) !important;
    border: 1px solid rgba(255, 225, 255, 0.24) !important;
    border-radius: 12px !important;
}


/* 16. PANEL INFERIOR */

[class*="panels_"] {
    background-color: rgba(42, 30, 53, 0.35) !important;
}


/* 17. MENÚS Y VENTANAS */

[class*="menu_"],
[class*="submenu_"],
[class*="popout_"],
[class*="modal_"],
[class*="userPopout_"],
[class*="userProfile_"] {
    background-color: rgba(42, 30, 53, 0.96) !important;
}


/* 18. BUSCADOR */

[class*="searchBar_"] {
    background-color: rgba(42, 30, 53, 0.48) !important;
    border-radius: 10px !important;
}


/* 19. BOTONES */

button:hover,
[class*="button_"]:hover {
    background-color: rgba(239, 199, 234, 0.20) !important;
}


/* 20. SCROLLBAR */

::-webkit-scrollbar {
    width: 6px !important;
}

::-webkit-scrollbar-thumb {
    background: rgba(239, 199, 234, 0.55) !important;
    border-radius: 20px !important;
}

::-webkit-scrollbar-track {
    background: transparent !important;
}


/* ==================================================
   FIN — LAVENDER DREAM
   ================================================== */
}
